// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');
const loadRobotoMono = makeLoadFont('RobotoMono');

const { fontFamily: spaceGrotesk } = loadSpaceGrotesk();
const { fontFamily: robotoMono } = loadRobotoMono();



export type NasdaqChartProps = Record<string, any>;

const NasdaqChart: React.FC<NasdaqChartProps> = ({
  backgroundColor = "#020205",
  transparentBackground = false,
  durationInSeconds = 10,
  lineColor = "#00d2ff",
  title = "NASDAQ",
  startValue = 13500,
  endValue = 15820,
  pointsCount = 60,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const durationFrames = durationInSeconds * fps;
  const paddingX = width * 0.08;
  const paddingY = height * 0.2;
  const chartWidth = width - paddingX * 2;
  const chartHeight = height - paddingY * 2;

  // Pre-calculate background style
  const bgStyle = transparentBackground
    ? "transparent"
    : `radial-gradient(circle at 50% 120%, ${lineColor}22, ${backgroundColor} 60%)`;

  // Generate deterministic chart points
  const points = useMemo(() => {
    const pts = [];
    for (let i = 0; i < pointsCount; i++) {
      const p = i / (pointsCount - 1);
      const x = interpolate(i, [0, pointsCount - 1], [0, chartWidth]);

      // Base upward trend mapping from lower down (0.8) to higher up (0.2)
      const baseY = interpolate(
        p,
        [0, 1],
        [chartHeight * 0.8, chartHeight * 0.2]
      );

      // Deterministic noise for organic stock movement
      const noise = (random(`nasdaq-noise-${i}`) - 0.5) * (chartHeight * 0.35);

      pts.push({ x, y: baseY + noise });
    }
    return pts;
  }, [pointsCount, chartWidth, chartHeight]);

  // Generate SVG Paths
  const { pathD, areaD } = useMemo(() => {
    let pD = "";
    let aD = "";
    points.forEach((pt, i) => {
      if (i === 0) {
        pD += `M ${pt.x} ${pt.y} `;
        aD += `M ${pt.x} ${chartHeight} L ${pt.x} ${pt.y} `;
      } else {
        pD += `L ${pt.x} ${pt.y} `;
        aD += `L ${pt.x} ${pt.y} `;
      }
    });
    aD += `L ${chartWidth} ${chartHeight} Z`;
    return { pathD: pD, areaD: aD };
  }, [points, chartWidth, chartHeight]);

  // Main animation progress
  const progress = interpolate(frame, [0, durationFrames * 0.75], [0, 1], {
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.ease),
  });

  // Calculate current indicator dot position
  const currentExactIndex = progress * (pointsCount - 1);
  const index1 = Math.floor(currentExactIndex);
  const index2 = Math.min(Math.ceil(currentExactIndex), pointsCount - 1);
  const fraction = currentExactIndex - index1;

  const currentX = interpolate(
    fraction,
    [0, 1],
    [points[index1].x, points[index2].x]
  );
  const currentY = interpolate(
    fraction,
    [0, 1],
    [points[index1].y, points[index2].y]
  );

  // Live Number Calculation
  const isAnimating = progress > 0 && progress < 1;
  const currentValue = interpolate(progress, [0, 1], [startValue, endValue]);
  const valueJitter = isAnimating
    ? (random(frame) - 0.5) * (endValue - startValue) * 0.02
    : 0;
  const finalDisplayValue = Math.max(0, currentValue + valueJitter);

  const diffPercent = (((endValue - startValue) / startValue) * 100).toFixed(2);
  const isPositive = endValue >= startValue;

  const formatNumber = (num: number) => {
    return num.toLocaleString("en-US", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });
  };

  // Intro Entry Animations
  const contentOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateRight: "clamp",
  });
  const contentY = interpolate(frame, [0, 20], [40, 0], {
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });

  return (
    <AbsoluteFill style={{ background: bgStyle }}>
      <div
        style={{
          width: "100%",
          height: "100%",
          display: "flex",
          flexDirection: "column",
          opacity: contentOpacity,
          transform: `translateY(${contentY}px)`,
          transition: "none",
        }}
      >
        {/* Header Section */}
        <div
          style={{
            position: "absolute",
            top: paddingY * 0.35,
            left: paddingX,
            display: "flex",
            flexDirection: "column",
          }}
        >
          <span
            style={{
              fontFamily: spaceGrotesk,
              color: "white",
              fontSize: 48,
              fontWeight: 700,
              letterSpacing: "0.05em",
            }}
          >
            {title}
          </span>
          <div style={{ display: "flex", alignItems: "baseline", gap: 24 }}>
            <span
              style={{
                fontFamily: robotoMono,
                color: "white",
                fontSize: 84,
                fontWeight: 600,
              }}
            >
              {formatNumber(finalDisplayValue)}
            </span>
            <span
              style={{
                fontFamily: robotoMono,
                color: isPositive ? lineColor : "#ff3366",
                fontSize: 36,
                fontWeight: 500,
              }}
            >
              {isPositive ? "+" : ""}
              {diffPercent}%
            </span>
          </div>
        </div>

        {/* Graph Section */}
        <div
          style={{
            position: "absolute",
            left: paddingX,
            top: paddingY * 1.2,
            width: chartWidth,
            height: chartHeight,
          }}
        >
          <svg
            width="100%"
            height="100%"
            style={{ overflow: "visible", transition: "none" }}
          >
            <defs>
              <linearGradient id="areaGradient" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor={lineColor} stopOpacity={0.5} />
                <stop offset="100%" stopColor={lineColor} stopOpacity={0.0} />
              </linearGradient>
              <clipPath id="revealClip">
                <rect
                  x="-20"
                  y="-100"
                  width={currentX + 20}
                  height={chartHeight + 200}
                />
              </clipPath>
            </defs>

            {/* Background Grid Lines */}
            {Array.from({ length: 5 }).map((_, i) => (
              <line
                key={i}
                x1="0"
                y1={(chartHeight / 4) * i}
                x2={chartWidth}
                y2={(chartHeight / 4) * i}
                stroke="rgba(255, 255, 255, 0.08)"
                strokeWidth={2}
                strokeDasharray="8 8"
              />
            ))}

            {/* X-Axis Timestamps */}
            {Array.from({ length: 6 }).map((_, i) => {
              const xPos = (chartWidth / 5) * i;
              return (
                <text
                  key={`time-${i}`}
                  x={xPos}
                  y={chartHeight + 40}
                  fill="rgba(255,255,255,0.4)"
                  fontFamily={robotoMono}
                  fontSize={20}
                  textAnchor={i === 0 ? "start" : i === 5 ? "end" : "middle"}
                >
                  {9 + i}:30 AM
                </text>
              );
            })}

            {/* Data Line and Fill */}
            <g clipPath="url(#revealClip)">
              <path d={areaD} fill="url(#areaGradient)" />
              <path
                d={pathD}
                fill="none"
                stroke={lineColor}
                strokeWidth={6}
                strokeLinecap="round"
                strokeLinejoin="round"
                style={{ filter: `drop-shadow(0px 4px 12px ${lineColor}66)` }}
              />
            </g>

            {/* Leading Pulse Dot */}
            <circle
              cx={currentX}
              cy={currentY}
              r={12}
              fill="#ffffff"
              stroke={lineColor}
              strokeWidth={5}
              style={{
                filter: `drop-shadow(0px 0px 16px ${lineColor})`,
                opacity: progress > 0.01 ? 1 : 0,
                transition: "none",
              }}
            />
          </svg>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default NasdaqChart;